find:
if(t.act==="sit"){
  var bn=t._gcaBench;
  if(!bn) t.actT=0;
  else {
    var st=t._gcaSeat, dd=Math.hypot(st.x-t.pos.x,st.z-t.pos.z);
    if(dd>.4&&t.actT>5){ m._move(t,e,st.x,st.z,1.5,st.x,st.z); t.state="act" }
    else {
      t.pos.x+=(st.x-t.pos.x)*Math.min(1,e*3); t.pos.z+=(st.z-t.pos.z)*Math.min(1,e*3);
      var dw=bn.yaw-t.yaw; t.yaw+=Math.atan2(Math.sin(dw),Math.cos(dw))*(1-Math.exp(-4*e));
      t.group.rotation.y=t.yaw;
    }
  }
}

